//! 🧬️ Vdi3805 artifact — document mutation dispatch. Semantic vocabulary derived from
//! `📸️snapshot/🦀️component.rs`'s `Vdi3805Snapshot` shape (manufacturer file header, catalog
//! products, edition-profile overrides, correction-as-of, strict mode, catalog index, parametric
//! geometry, characteristic curves, security limits) per
//! `.🦑️repo/🎫️tickets/🎆️26/🌙️08/☀️12/SEMANTIC-MUTATIONS-OVERHAUL/📓️taxonomy.md`/
//! `📓️derivation-rules.md`. `impl protocol::Mutation`/`SemanticMutation` below are generated by
//! `#[derive(dsl::Mutations)]` (re-exported from `dsl_derive::Mutations` — consuming plugin crates
//! reach it through the `dsl` extern-crate alias `📦️glue.rs` already declares, not the proc-macro
//! crate name directly) — never hand-written.
//!
//! `catalog.index` is persisted state that mirrors `catalog.products` one-to-one
//! (`CatalogIndex::from_catalog`'s per-product mapping) — every product mutation (`create`/
//! `rename`/`replace-configuration`/`delete`) keeps it in lockstep via the `🔖️IndexSync` helpers
//! below, rather than letting it silently drift out of sync with the catalog it indexes.
//!
//! Every triad leaf is mounted directly as a `mutations`-sibling module in `📦️glue.rs` (this lane's
//! agent owns `📦️glue.rs`, so no self-wiring `#[path = "."]` blocks are needed here — the orphaned
//! `📄set-snapshot` stub is deleted along with its dangling glue mount).

use crate::artifacts::vdi3805::{CatalogIndexEntry, CatalogueProduct, Vdi3805Diff, Vdi3805Snapshot, VdiValue};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;

//#region 🔖️IndexSync
/// 🧮️ Mirrors `CatalogIndex::from_catalog`'s per-product mapping — kept here so every product
/// mutation (`create`/`rename`/`replace-configuration`) can update the persisted `index` field
/// directly from the payload instead of rebuilding the whole index from the whole catalog.
pub async fn catalog_index_entry_for(product: &CatalogueProduct) -> CatalogIndexEntry {
    CatalogIndexEntry { product_id: product.identity.article_number.clone(), sheet: product.sheet, tags: product.title.iter().map(|t| t.text.clone()).collect(), dn: extract_dn(&product.configuration.parameters) }
}

/// 🔢️ Extracts a `CatalogIndexEntry.dn` value from a configuration's parameter bag, mirroring
/// `CatalogIndex::from_catalog`'s own extraction exactly.
pub async fn extract_dn(parameters: &BTreeMap<String, VdiValue>) -> Option<u16> {
    parameters.get("dn").and_then(|v| match v {
        VdiValue::Integer { value } => Some(*value as u16),
        VdiValue::Decimal { value, .. } => Some(*value as u16),
        _ => None,
    })
}
//#endregion 🔖️IndexSync

